head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.tooltipFormatter = function(id, label) {
    debugger;
}
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var el = WebSquare.wUnit.getDomById(id);
    scwin.fireOver(el);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 개발자모드에서 div태그로 랜더링 되어있는 id = 'wq_uuid_1_tooltip'의 class값을 확인한다.
    //1. After executing the sample, check the class value of id = 'wq_uuid_1_tooltip' which is rendered with div tag in developer mode.
    //Verify step 1. class = 'w2textbox_tooltip'
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('body').css('width', '50%')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour($p.id+'wq_uuid_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_1_tooltip').hasClass('w2textbox_tooltip')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 동일하게 id = 'wq_uuid_11_tooltip'의 class값을 확인한다.
    //2. Identify the class value of id = 'wq_uuid_11_tooltip' in the same way.
    //Verify step 1. class = 'w2group_tooltip'
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour($p.id+'wq_uuid_11')");
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_11_tooltip').hasClass('w2group_tooltip')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 06-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
